import type { DreamSymbol, Feeling } from './types.ts';

type Cat = DreamSymbol['category'];
// Compact builder: feelings are given in the order fear, calm, joy, sad, anger, confused.
const s = (
  id: string,
  name: string,
  category: Cat,
  words: string[],
  folk: string,
  psyche: string,
  craft: string | undefined,
  f: [string, string, string, string, string, string],
  questions: string[],
  action?: string,
): DreamSymbol => {
  const byFeeling: Record<Feeling, string> = {
    fear: f[0],
    calm: f[1],
    joy: f[2],
    sad: f[3],
    anger: f[4],
    confused: f[5],
  };
  return { id, name, category, words, folk, psyche, ...(craft ? { craft } : {}), byFeeling, questions, ...(action ? { action } : {}) };
};

